package truth

// Purpose: find the spans of a file a claim rule must not judge: generated
// regions, JSX expressions, Astro code, lines under a `truth: exempt` comment.
// Inputs:  a file's repo-relative path and its lines.
// Outputs: a fileMask answering "is this match exempt?" and listing the
// `truth: exempt` comments that carry no reason.
// Constraints: Epic TRUTH D6. A region is exempt only when both its markers are
// present and their id is declared with a reason; GENERATED BY headers
// do not grant exemptions; JSX expressions count only in
// .astro and .mdx, only when the braces balance, and never inside a code fence;
// Astro frontmatter is scanned conservatively, including its strings;
// <script> and <style> blocks remain exempt;
// the exempt comment covers the next line only; no file or network access.

import (
	"regexp"
	"sort"
	"strings"
)

var (
	// Markers are HTML comments, or JSX comments in .mdx (MDX 2 rejects <!-- -->).
	beginRe  = regexp.MustCompile(`(?:<!--|\{/\*)\s*BEGIN GENERATED:([A-Za-z0-9._:-]+)\s*(?:-->|\*/\})`)
	endRe    = regexp.MustCompile(`(?:<!--|\{/\*)\s*END GENERATED:([A-Za-z0-9._:-]+)\s*(?:-->|\*/\})`)
	exemptRe = regexp.MustCompile(`^(?:<!--|\{/\*)\s*truth:\s*exempt(?:\s(.*?))?\s*(?:-->|\*/\})$`)
	wordsRe  = regexp.MustCompile(`[A-Za-z0-9]`)
	codeTag  = regexp.MustCompile(`<(script|style)(?:[\s>/]|$)`) // lower case only: <Script> is an Astro component
)

// fileMask is the exempt part of one file.
type fileMask struct {
	whole    []bool   // line i (0-based) is exempt as a whole
	starts   []int    // byte offset of each line in the joined text
	spans    [][2]int // JSX expression spans as byte offsets in the joined text
	text     string   // the lines joined with \n (for stringOnly)
	NoReason []int    // 1-based lines of `truth: exempt` comments without a reason
}

// analyze computes the mask of one file.
func analyze(rel string, lines []string, declared map[string]string) fileMask {
	m := fileMask{whole: make([]bool, len(lines)), starts: make([]int, len(lines))}
	off := 0
	for i, l := range lines {
		m.starts[i] = off
		off += len(l) + 1
	}
	m.text = strings.Join(lines, "\n")
	m.generatedRegions(lines, declared)
	m.exemptComments(lines)
	ext := strings.ToLower(rel[strings.LastIndex(rel, ".")+1:])
	if ext == "astro" || ext == "mdx" {
		m.jsx(lines, ext == "astro")
	}
	return m
}

func (m *fileMask) generatedRegions(lines []string, declared map[string]string) {
	for i := 0; i < len(lines); i++ {
		g := beginRe.FindStringSubmatch(lines[i])
		if g == nil || declared[g[1]] == "" {
			continue
		}
		for j := i + 1; j < len(lines); j++ {
			if b := beginRe.FindStringSubmatch(lines[j]); b != nil && b[1] == g[1] {
				break // the first BEGIN is unclosed: it exempts nothing
			}
			if e := endRe.FindStringSubmatch(lines[j]); e != nil && e[1] == g[1] {
				for k := i; k <= j; k++ {
					m.whole[k] = true
				}
				i = j
				break
			}
		}
	}
}

func (m *fileMask) exemptComments(lines []string) {
	fence := false
	for i, l := range lines {
		t := strings.TrimSpace(l)
		if strings.HasPrefix(t, "```") || strings.HasPrefix(t, "~~~") {
			fence = !fence
			continue
		}
		g := exemptRe.FindStringSubmatch(t) // the marker is the whole line: prose that mentions it exempts nothing
		if g == nil || fence {
			continue
		}
		if len(wordsRe.FindAllString(g[1], -1)) < 4 { // a reason has at least four letters or digits
			m.NoReason = append(m.NoReason, i+1)
			continue
		}
		if i+1 < len(lines) {
			m.whole[i+1] = true
		}
	}
}

// jsx marks Astro code blocks and brace expressions.
func (m *fileMask) jsx(lines []string, astro bool) {
	fence, depth, open := false, 0, 0
	inFront, inCode := false, ""
	for i, l := range lines {
		t := strings.TrimSpace(l)
		if astro {
			if i == 0 && t == "---" {
				inFront = true
				m.whole[i] = true
				continue
			}
			if inFront {
				inFront = t != "---"
				continue
			}
			if inCode != "" {
				m.whole[i] = true
				if strings.Contains(strings.ToLower(l), "</"+inCode) { // closing tag of the code block
					inCode = ""
				}
				continue
			}
			if loc := codeTag.FindStringSubmatchIndex(l); loc != nil {
				tag, rest := l[loc[2]:loc[3]], l[loc[3]:]
				// A block opens only when the open tag ends on this line without "/>" and has no closing tag after it.
				if gt := strings.Index(rest, ">"); gt >= 0 && !strings.HasSuffix(strings.TrimSpace(rest[:gt+1]), "/>") && !strings.Contains(rest, "</"+tag) {
					inCode = tag
					m.whole[i] = true
				}
			}
			if inCode != "" {
				continue
			}
		}
		if strings.HasPrefix(t, "```") || strings.HasPrefix(t, "~~~") {
			fence = !fence
			continue
		}
		if fence {
			continue
		}
		if t == "" { // an expression never spans a blank line: a stray brace cannot exempt a paragraph
			depth = 0
			continue
		}
		code := false
		for c := 0; c < len(l); c++ {
			if l[c] == '`' {
				code = !code
			}
			if code {
				continue
			}
			switch l[c] {
			case '{':
				if depth == 0 {
					open = m.starts[i] + c
				}
				depth++
			case '}':
				if depth > 0 {
					depth--
					if depth == 0 {
						end := m.starts[i] + c + 1
						if !m.stringOnly(open, end) {
							m.spans = append(m.spans, [2]int{open, end})
						}
					}
				}
			}
		}
	}
}

// stringOnly reports whether the expression [open,end) is just a quoted
// string or a template literal without ${}: that prints typed text, not a value.
func (m fileMask) stringOnly(open, end int) bool {
	if m.text == "" || end-open < 4 {
		return false
	}
	in := strings.TrimSpace(m.text[open+1 : end-1])
	if len(in) < 2 || in[0] != in[len(in)-1] || !strings.ContainsRune("\"'`", rune(in[0])) {
		return false
	}
	return !strings.Contains(in[1:len(in)-1], "${") && !strings.ContainsRune(in[1:len(in)-1], rune(in[0]))
}

// exempt reports whether the hit [start,end) on 0-based line i is inside an exempt part.
func (m fileMask) exempt(i, start, end int) bool {
	if m.whole[i] {
		return true
	}
	s, e := m.starts[i]+start, m.starts[i]+end
	return spansCover(m.spans, s, e)
}

// spansCover reports whether one of the sorted, non-overlapping spans holds [s,e).
func spansCover(spans [][2]int, s, e int) bool {
	k := sort.Search(len(spans), func(j int) bool { return spans[j][1] > s })
	return k < len(spans) && spans[k][0] <= s && e <= spans[k][1]
}
